
"""Build deterministic image fixtures without runtime Python dependencies."""

from __future__ import annotations

import base64
from pathlib import Path
from subprocess import run
from tempfile import TemporaryDirectory

from tests.fixtures.pdf.builders import create_native_pdf


_BLANK_IMAGES = {
    "jpeg": "",
    "png": "iVBORw0KGgoAAAANSUhEUgAAACAAAAAYCAIAAAAUMWhjAAAAJklEQVR4nO3NMQEAAAjDMMC/52ECvlRA00nqs3m9AwAAAAAAAJy1C7oDLV5LB/0AAAAASUVORK5CYII=",
    "tiff": "",
    "webp": "UklGRjIAAABXRUJQVlA4ICYAAADQAgCdASogABgAPm00lkekIyIhKAgAgA2JaQAAPaOgAP77IYAAAA==",
}


def write_blank_image(path: Path, format_id: str) -> Path:
    path.write_bytes(base64.b64decode(_BLANK_IMAGES[format_id]))
    return path


def create_document_png(
    path: Path,
    lines: tuple[str, ...],
    dpi: int = 200,
) -> Path:
    with TemporaryDirectory() as directory:
        source = Path(directory) / "source.pdf"
        create_native_pdf(source, lines)
        output_root = Path(directory) / "page"
        process = run(
            [
                "pdftoppm",
                "-f", "1",
                "-l", "1",
                "-singlefile",
                "-png",
                "-r", str(dpi),
                str(source),
                str(output_root),
            ],
            capture_output=True,
            check=False,
        )
        generated = output_root.with_suffix(".png")
        if process.returncode != 0 or not generated.exists():
            raise RuntimeError(
                process.stderr.decode("utf-8", errors="replace")
                or "pdftoppm failed while building an image fixture."
            )
        path.write_bytes(generated.read_bytes())
    return path
